import React, { useState, useEffect, useRef } from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createStackNavigator } from '@react-navigation/stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Ionicons } from '@expo/vector-icons';
import * as Linking from 'expo-linking';
import { Alert } from 'react-native';
import { isAuthenticated, getCurrentUser, type User } from '../lib/auth';

import LandingScreen from '../screens/LandingScreen';
import SignInScreen from '../screens/SignInScreen';
import SignUpScreen from '../screens/SignUpScreen';
import DashboardScreen from '../screens/DashboardScreen';
import VaultScreen from '../screens/VaultScreen';
import ChatScreen from '../screens/ChatScreen';
import PasswordsScreen from '../screens/PasswordsScreen';
import ProfileScreen from '../screens/ProfileScreen';
import SubscriptionScreen from '../screens/SubscriptionScreen';
import UpgradeScreen from '../screens/UpgradeScreen';
import AdminScreen from '../screens/AdminScreen';
import AdminSettingsScreen from '../screens/AdminSettingsScreen';
import AdminPaymentsScreen from '../screens/AdminPaymentsScreen';

const Stack = createStackNavigator();
const Tab = createBottomTabNavigator();

function AuthNavigator() {
  return (
    <Stack.Navigator screenOptions={{ headerShown: false }}>
      <Stack.Screen name="Landing" component={LandingScreen} />
      <Stack.Screen name="SignIn" component={SignInScreen} />
      <Stack.Screen name="SignUp" component={SignUpScreen} />
    </Stack.Navigator>
  );
}

function MainTabs() {
  const [userRole, setUserRole] = useState<'loading' | 'admin' | 'user'>('loading');

  useEffect(() => {
    const checkAdminStatus = async () => {
      const user = await getCurrentUser();
      // Only update role if we have a valid user with a definitive role
      if (user && user.role) {
        const newRole = user.role as 'admin' | 'user';
        setUserRole(newRole);
      } else if (user && !user.role) {
        // User exists but has no role property, default to 'user'
        setUserRole('user');
      }
      // If user is null/undefined, keep current role (don't downgrade admin to user)
    };

    checkAdminStatus();

    // Re-check admin status periodically to handle auth changes
    const interval = setInterval(checkAdminStatus, 1000);

    return () => clearInterval(interval);
  }, []);

  // Show nothing while loading
  if (userRole === 'loading') {
    return null;
  }

  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        tabBarIcon: ({ focused, color, size }) => {
          let iconName: keyof typeof Ionicons.glyphMap;

          if (route.name === 'Dashboard') {
            iconName = focused ? 'home' : 'home-outline';
          } else if (route.name === 'Vault') {
            iconName = focused ? 'folder' : 'folder-outline';
          } else if (route.name === 'Smart Finder') {
            iconName = focused ? 'chatbubbles' : 'chatbubbles-outline';
          } else if (route.name === 'Passwords') {
            iconName = focused ? 'lock-closed' : 'lock-closed-outline';
          } else if (route.name === 'Profile') {
            iconName = focused ? 'person' : 'person-outline';
          } else if (route.name === 'Admin Dashboard') {
            iconName = focused ? 'shield-checkmark' : 'shield-checkmark-outline';
          } else if (route.name === 'Admin Settings') {
            iconName = focused ? 'settings' : 'settings-outline';
          } else if (route.name === 'Payments') {
            iconName = focused ? 'cash' : 'cash-outline';
          } else {
            iconName = focused ? 'settings' : 'settings-outline';
          }

          return <Ionicons name={iconName} size={size} color={color} />;
        },
        tabBarActiveTintColor: '#007AFF',
        tabBarInactiveTintColor: 'gray',
        headerShown: true,
      })}
    >
      {userRole === 'admin' ? (
        <>
          <Tab.Screen name="Admin Dashboard" component={AdminScreen} />
          <Tab.Screen name="Admin Settings" component={AdminSettingsScreen} />
          <Tab.Screen name="Payments" component={AdminPaymentsScreen} />
        </>
      ) : (
        <>
          <Tab.Screen name="Dashboard" component={DashboardScreen} />
          <Tab.Screen name="Vault" component={VaultScreen} />
          <Tab.Screen name="Smart Finder" component={ChatScreen} />
          <Tab.Screen name="Passwords" component={PasswordsScreen} />
          <Tab.Screen name="Profile" component={ProfileScreen} />
        </>
      )}
    </Tab.Navigator>
  );
}

function MainStack() {
  return (
    <Stack.Navigator>
      <Stack.Screen 
        name="MainTabs" 
        component={MainTabs} 
        options={{ headerShown: false }}
      />
      <Stack.Screen 
        name="Subscription" 
        component={SubscriptionScreen}
        options={{ title: 'Subscription' }}
      />
      <Stack.Screen 
        name="Upgrade" 
        component={UpgradeScreen}
        options={{ title: 'Upgrade Plan' }}
      />
    </Stack.Navigator>
  );
}

export default function AppNavigator() {
  const [authenticated, setAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const navigationRef = useRef<any>(null);
  const pendingDeepLink = useRef<{ hostname: string; path: string } | null>(null);

  useEffect(() => {
    const checkAuth = async () => {
      const authStatus = await isAuthenticated();
      setAuthenticated(authStatus);
      setLoading(false);
    };

    checkAuth();

    // Set up an interval to check auth status periodically
    const interval = setInterval(checkAuth, 1000);

    return () => clearInterval(interval);
  }, []);

  // Process pending deep link when navigation is ready
  useEffect(() => {
    if (!loading && navigationRef.current && pendingDeepLink.current) {
      const { hostname, path } = pendingDeepLink.current;
      pendingDeepLink.current = null; // Clear pending link

      if (hostname === 'payment' && path === 'success') {
        Alert.alert(
          'Payment Successful!',
          'Your subscription has been updated. Please wait a moment while we process your payment.',
          [
            {
              text: 'OK',
              onPress: () => {
                navigationRef.current?.navigate('Subscription');
              },
            },
          ]
        );
      } else if (hostname === 'payment' && path === 'cancel') {
        Alert.alert(
          'Payment Canceled',
          'Your payment was canceled. You can try again anytime.',
          [
            {
              text: 'OK',
              onPress: () => {
                navigationRef.current?.navigate('Upgrade');
              },
            },
          ]
        );
      }
    }
  }, [loading]);

  // Handle deep links for Stripe checkout redirect
  useEffect(() => {
    const handleDeepLink = async (event: { url: string }) => {
      const { hostname, path, queryParams } = Linking.parse(event.url);

      console.log('Deep link received:', { hostname, path, queryParams, loading, navReady: !!navigationRef.current });

      // Only handle payment deep links
      if (hostname === 'payment' && (path === 'success' || path === 'cancel')) {
        // Queue the deep link if navigator isn't ready yet
        if (loading || !navigationRef.current) {
          console.log('Navigator not ready, queuing deep link');
          pendingDeepLink.current = { hostname, path };
          return;
        }

        // Navigator is ready, process immediately
        // Expo's Linking.parse splits zorliapp://payment/success into hostname='payment' and path='success'
        if (path === 'success') {
          Alert.alert(
            'Payment Successful!',
            'Your subscription has been updated. Please wait a moment while we process your payment.',
            [
              {
                text: 'OK',
                onPress: () => {
                  navigationRef.current?.navigate('Subscription');
                },
              },
            ]
          );
        } else if (path === 'cancel') {
          Alert.alert(
            'Payment Canceled',
            'Your payment was canceled. You can try again anytime.',
            [
              {
                text: 'OK',
                onPress: () => {
                  navigationRef.current?.navigate('Upgrade');
                },
              },
            ]
          );
        }
      }
    };

    // Listen for deep links when app is already open
    const subscription = Linking.addEventListener('url', handleDeepLink);

    // Check if app was opened with a deep link
    Linking.getInitialURL().then((url: string | null) => {
      if (url) {
        handleDeepLink({ url });
      }
    });

    return () => {
      subscription.remove();
    };
  }, [loading]);

  if (loading) {
    return null;
  }

  return (
    <NavigationContainer ref={navigationRef}>
      {authenticated ? <MainStack /> : <AuthNavigator />}
    </NavigationContainer>
  );
}

mobile/src/screens/SignInScreen.tsx.content:
import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  Alert,
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Modal,
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { signIn } from '../lib/auth';
import { ZorliBrandKit } from '../theme/zorli-brand-kit';

const API_URL = process.env.EXPO_PUBLIC_API_URL || '';

export default function SignInScreen({ navigation }: any) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Forgot Password States
  const [showForgotPasswordModal, setShowForgotPasswordModal] = useState(false);
  const [showResetPasswordModal, setShowResetPasswordModal] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isRequestingOTP, setIsRequestingOTP] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

  const handleSignIn = async () => {
    if (!email || !password) {
      Alert.alert('Error', 'Please fill in all fields');
      return;
    }

    setLoading(true);
    const result = await signIn(email, password);
    setLoading(false);

    if (!result.success || result.error) {
      Alert.alert('Sign In Failed', result.error || 'Invalid email or password');
    }
    // Navigation happens automatically when auth state changes in AppNavigator
  };

  const handleForgotPassword = async () => {
    if (!resetEmail) {
      Alert.alert('Error', 'Please enter your email address');
      return;
    }

    setIsRequestingOTP(true);
    try {
      const response = await fetch(`${API_URL}/api/auth/forgot-password`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email: resetEmail }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || 'Failed to send reset code');
      }

      Alert.alert('Success', 'Check your email for the 6-digit code');
      setShowForgotPasswordModal(false);
      setShowResetPasswordModal(true);
    } catch (error: any) {
      Alert.alert('Error', error.message || 'Failed to send reset code. Please try again.');
    } finally {
      setIsRequestingOTP(false);
    }
  };

  const handleResetPassword = async () => {
    if (!otp || !newPassword || !confirmPassword) {
      Alert.alert('Error', 'Please fill in all fields');
      return;
    }

    if (otp.length !== 6) {
      Alert.alert('Error', 'OTP must be 6 digits');
      return;
    }

    if (newPassword.length < 8) {
      Alert.alert('Error', 'Password must be at least 8 characters');
      return;
    }

    if (newPassword !== confirmPassword) {
      Alert.alert('Error', 'Passwords do not match');
      return;
    }

    setIsResettingPassword(true);
    try {
      const response = await fetch(`${API_URL}/api/auth/reset-password`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email: resetEmail,
          otp,
          newPassword,
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || 'Failed to reset password');
      }

      Alert.alert('Success', 'Your password has been reset successfully. Please sign in again.');
      setShowResetPasswordModal(false);
      setResetEmail('');
      setOtp('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (error: any) {
      Alert.alert('Error', error.message || 'Invalid or expired OTP. Please try again.');
    } finally {
      setIsResettingPassword(false);
    }
  };

  return (
    <KeyboardAvoidingView 
      style={styles.container} 
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <View style={styles.content}>
        <Text style={styles.title}>Zorli AI Vault</Text>
        <Text style={styles.subtitle}>Sign in to your account</Text>

        <TextInput
          style={styles.input}
          placeholder="Email"
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          keyboardType="email-address"
        />

        <View style={styles.passwordContainer}>
          <TextInput
            style={styles.passwordInput}
            placeholder="Password"
            value={password}
            onChangeText={setPassword}
            secureTextEntry={!showPassword}
          />
          <TouchableOpacity
            style={styles.eyeIcon}
            onPress={() => setShowPassword(!showPassword)}
          >
            <Ionicons
              name={showPassword ? 'eye-off' : 'eye'}
              size={24}
              color="#666"
            />
          </TouchableOpacity>
        </View>

        <TouchableOpacity 
          onPress={() => {
            setResetEmail(email);
            setShowForgotPasswordModal(true);
          }}
          style={styles.forgotPasswordButton}
        >
          <Text style={styles.forgotPasswordText}>Forgot password?</Text>
        </TouchableOpacity>

        <TouchableOpacity 
          style={styles.button} 
          onPress={handleSignIn}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.buttonText}>Sign In</Text>
          )}
        </TouchableOpacity>

        <TouchableOpacity onPress={() => navigation.navigate('SignUp')}>
          <Text style={styles.link}>Don't have an account? Sign Up</Text>
        </TouchableOpacity>
      </View>

      {/* Forgot Password Modal - Email Input */}
      <Modal
        visible={showForgotPasswordModal}
        transparent
        animationType="slide"
        onRequestClose={() => setShowForgotPasswordModal(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <Text style={styles.modalTitle}>Reset your password</Text>
            <Text style={styles.modalSubtitle}>
              Enter your email address and we'll send you a 6-digit code to reset your password.
            </Text>

            <TextInput
              style={styles.input}
              placeholder="Email"
              value={resetEmail}
              onChangeText={setResetEmail}
              autoCapitalize="none"
              keyboardType="email-address"
            />

            <View style={styles.modalButtons}>
              <TouchableOpacity
                style={[styles.modalButton, styles.modalButtonSecondary]}
                onPress={() => setShowForgotPasswordModal(false)}
                disabled={isRequestingOTP}
              >
                <Text style={styles.modalButtonTextSecondary}>Cancel</Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.modalButton, styles.modalButtonPrimary]}
                onPress={handleForgotPassword}
                disabled={isRequestingOTP}
              >
                {isRequestingOTP ? (
                  <ActivityIndicator color="#fff" />
                ) : (
                  <Text style={styles.modalButtonTextPrimary}>Send Code</Text>
                )}
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* Reset Password Modal - OTP & New Password */}
      <Modal
        visible={showResetPasswordModal}
        transparent
        animationType="slide"
        onRequestClose={() => setShowResetPasswordModal(false)}
      >
        <View style={styles.modalOverlay}>
          <KeyboardAvoidingView 
            behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
            style={styles.modalKeyboardAvoid}
          >
            <ScrollView contentContainerStyle={styles.modalScrollContent}>
              <View style={styles.modalContent}>
                <Text style={styles.modalTitle}>Enter reset code</Text>
                <Text style={styles.modalSubtitle}>
                  We sent a 6-digit code to {resetEmail}. Enter it below along with your new password.
                </Text>

                <TextInput
                  style={styles.input}
                  placeholder="6-Digit Code"
                  value={otp}
                  onChangeText={setOtp}
                  keyboardType="number-pad"
                  maxLength={6}
                />

                <View style={styles.passwordContainer}>
                  <TextInput
                    style={styles.passwordInput}
                    placeholder="New Password"
                    value={newPassword}
                    onChangeText={setNewPassword}
                    secureTextEntry={!showNewPassword}
                  />
                  <TouchableOpacity
                    style={styles.eyeIcon}
                    onPress={() => setShowNewPassword(!showNewPassword)}
                  >
                    <Ionicons
                      name={showNewPassword ? 'eye-off' : 'eye'}
                      size={24}
                      color="#666"
                    />
                  </TouchableOpacity>
                </View>

                <View style={styles.passwordContainer}>
                  <TextInput
                    style={styles.passwordInput}
                    placeholder="Confirm New Password"
                    value={confirmPassword}
                    onChangeText={setConfirmPassword}
                    secureTextEntry={!showConfirmPassword}
                  />
                  <TouchableOpacity
                    style={styles.eyeIcon}
                    onPress={() => setShowConfirmPassword(!showConfirmPassword)}
                  >
                    <Ionicons
                      name={showConfirmPassword ? 'eye-off' : 'eye'}
                      size={24}
                      color="#666"
                    />
                  </TouchableOpacity>
                </View>

                <View style={styles.modalButtons}>
                  <TouchableOpacity
                    style={[styles.modalButton, styles.modalButtonSecondary]}
                    onPress={() => {
                      setShowResetPasswordModal(false);
                      setShowForgotPasswordModal(true);
                    }}
                    disabled={isResettingPassword}
                  >
                    <Text style={styles.modalButtonTextSecondary}>Back</Text>
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={[styles.modalButton, styles.modalButtonPrimary]}
                    onPress={handleResetPassword}
                    disabled={isResettingPassword}
                  >
                    {isResettingPassword ? (
                      <ActivityIndicator color="#fff" />
                    ) : (
                      <Text style={styles.modalButtonTextPrimary}>Reset Password</Text>
                    )}
                  </TouchableOpacity>
                </View>
              </View>
            </ScrollView>
          </KeyboardAvoidingView>
        </View>
      </Modal>
    </KeyboardAvoidingView>
  );
}

