// Backward compatibility
export const insertFileSchema = insertDocumentSchema;

export const insertJobSchema = createInsertSchema(jobs).pick({
  userId: true,
  jobType: true,
  status: true,
  data: true,
});

export const insertTextChunkSchema = createInsertSchema(textChunks).pick({
  fileId: true,
  userId: true,
  content: true,
  chunkIndex: true,
  metadata: true,
});

export const insertSubscriptionPlanSchema = createInsertSchema(subscriptionPlans).pick({
  name: true,
  displayName: true,
  description: true,
  priceMonthly: true,
  stripePriceId: true,
  maxFiles: true,
  maxAIPrompts: true,
  features: true,
});

export const insertUserSubscriptionSchema = createInsertSchema(userSubscriptions).pick({
  userId: true,
  planId: true,
  stripeSubscriptionId: true,
  stripeCustomerId: true,
  status: true,
  currentPeriodStart: true,
  currentPeriodEnd: true,
  trialStart: true,
  trialEnd: true,
  cancelAtPeriodEnd: true,
});

export const insertAccountCredentialSchema = createInsertSchema(accountCredentials).pick({
  userId: true,
  serviceName: true,
  username: true,
  encryptedPassword: true,
  passwordHint: true,
  website: true,
  notes: true,
  category: true,
  isFavorite: true,
});

export const insertSubscriptionUsageSchema = createInsertSchema(subscriptionUsage).pick({
  userId: true,
  subscriptionId: true,
  filesCount: true,
  passwordsCount: true,
  aiPromptsCount: true,
  storageUsedBytes: true,
});

export const insertPaymentSchema = createInsertSchema(payments).pick({
  paymentId: true,
  userId: true,
  plan: true,
  amount: true,
  currency: true,
  status: true,
  subscriptionId: true,
  invoiceId: true,
  periodStart: true,
  periodEnd: true,
  metadata: true,
});

export const insertEmailVerificationTokenSchema = createInsertSchema(emailVerificationTokens).pick({
  userId: true,
  token: true,
  expiresAt: true,
});

export const insertPasswordResetSchema = createInsertSchema(passwordResets).pick({
  email: true,
  otp: true,
  expiresAt: true,
});

// Types
export type User = typeof users.$inferSelect;
export type InsertUser = z.infer<typeof insertUserSchema>;

export type DocumentRecord = typeof documents.$inferSelect;
