import OpenAI from 'openai'

// Initialize OpenAI client
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
})

// the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
const DEFAULT_MODEL = 'gpt-5'

export interface AIAnalysisResult {
  summary: string
  sentiment: {
    rating: number
    confidence: number
  }
  tags: string[]
  category: string
}

export interface ImageAnalysisResult {
  description: string
  objects: string[]
  scene: string
  text_content?: string
}

export class AIService {
  // Text analysis and summarization
  static async analyzeText(text: string): Promise<AIAnalysisResult> {
    try {
      const response = await openai.chat.completions.create({
        model: DEFAULT_MODEL,
        messages: [
          {
            role: 'system',
            content: `Analyze the following text and return a JSON response with:
              - summary: A concise summary of the text
              - sentiment: { rating: number (1-5), confidence: number (0-1) }
              - tags: Array of relevant tags/keywords
              - category: Main category/topic

              Respond only with valid JSON.`
          },
          {
            role: 'user',
            content: text
          }
        ],
        response_format: { type: 'json_object' }
      })

      const result = JSON.parse(response.choices[0].message.content || '{}')
      return result as AIAnalysisResult
    } catch (error) {
      console.error('AI text analysis failed:', error)
      throw new Error('Failed to analyze text with AI')
    }
  }

  // Image analysis
  static async analyzeImage(base64Image: string): Promise<ImageAnalysisResult> {
    try {
      const response = await openai.chat.completions.create({
        model: DEFAULT_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'text',
                text: 'Analyze this image and return a JSON response with: description, objects (array), scene, and text_content (if any text is visible). Respond only with valid JSON.'
              },
              {
                type: 'image_url',
                image_url: {
                  url: `data:image/jpeg;base64,${base64Image}`
                }
              }
            ]
          }
        ],
        response_format: { type: 'json_object' },
        max_completion_tokens: 1024
      })

      const result = JSON.parse(response.choices[0].message.content || '{}')
      return result as ImageAnalysisResult
    } catch (error) {
      console.error('AI image analysis failed:', error)
      throw new Error('Failed to analyze image with AI')
    }
  }

  // Generate image from text prompt
  static async generateImage(prompt: string): Promise<{ url: string }> {
    try {
      const response = await openai.images.generate({
        model: 'dall-e-3',
        prompt,
        n: 1,
        size: '1024x1024',
        quality: 'standard'
      })

      return { url: response.data?.[0]?.url || '' }
    } catch (error) {
      console.error('AI image generation failed:', error)
      throw new Error('Failed to generate image with AI')
    }
  }

  // Transcribe audio
  static async transcribeAudio(audioFile: File): Promise<{ text: string; duration?: number }> {
    try {
      const response = await openai.audio.transcriptions.create({
        file: audioFile,
        model: 'whisper-1'
      })

      return {
        text: response.text,
        duration: undefined
      }
    } catch (error) {
      console.error('AI audio transcription failed:', error)
      throw new Error('Failed to transcribe audio with AI')
    }
  }
}

export { openai }

mobile/src/screens/SignUpScreen.tsx.content:
import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  Alert,
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { signUp } from '../lib/auth';
import { ZorliBrandKit } from '../theme/zorli-brand-kit';

export default function SignUpScreen({ navigation }: any) {
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [emailSent, setEmailSent] = useState(false);

  const handleSignUp = async () => {
    if (!firstName || !lastName || !email || !password || !confirmPassword) {
      Alert.alert('Error', 'Please fill in all fields');
      return;
    }

    if (password !== confirmPassword) {
      Alert.alert('Error', 'Passwords do not match');
      return;
    }

    if (password.length < 8) {
      Alert.alert('Error', 'Password must be at least 8 characters');
      return;
    }

    setLoading(true);
    const result = await signUp(firstName, lastName, email, password);
    setLoading(false);

    if (!result.success || result.error) {
      Alert.alert('Sign Up Failed', result.error || 'Failed to create account');
    } else {
      setEmailSent(true);
      Alert.alert(
        'Account Created!',
        result.message || 'Please check your email to verify your account.',
        [{ text: 'OK' }]
      );
    }
  };

  if (emailSent) {
    return (
      <View style={styles.container}>
        <View style={styles.content}>
          <View style={styles.successIcon}>
            <Ionicons name="mail-outline" size={64} color={ZorliBrandKit.colors.successGreen} />
          </View>
          <Text style={styles.successTitle}>Verification Email Sent</Text>
          <Text style={styles.successMessage}>
            We've sent a verification link to your email address. Please check your inbox and click the "Verify & Login" button to activate your account.
          </Text>
          <View style={styles.infoBox}>
            <Ionicons name="information-circle-outline" size={20} color={ZorliBrandKit.colors.vaultBlue} />
            <Text style={styles.infoText}>
              The verification link will expire in 30 minutes.
            </Text>
          </View>
          <TouchableOpacity 
            style={styles.button} 
            onPress={() => navigation.navigate('SignIn')}
          >
            <Text style={styles.buttonText}>Go to Sign In</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <KeyboardAvoidingView 
      style={styles.container} 
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <ScrollView contentContainerStyle={styles.scrollContent}>
        <View style={styles.content}>
          <Text style={styles.title}>Create Account</Text>
          <Text style={styles.subtitle}>Join Zorli AI Vault</Text>

          <TextInput
            style={styles.input}
            placeholder="First Name"
            value={firstName}
            onChangeText={setFirstName}
            autoCapitalize="words"
          />

          <TextInput
            style={styles.input}
            placeholder="Last Name"
            value={lastName}
            onChangeText={setLastName}
            autoCapitalize="words"
          />

          <TextInput
            style={styles.input}
            placeholder="Email"
            value={email}
            onChangeText={setEmail}
            autoCapitalize="none"
            keyboardType="email-address"
          />

          <View style={styles.passwordContainer}>
            <TextInput
              style={styles.passwordInput}
              placeholder="Password"
              value={password}
              onChangeText={setPassword}
              secureTextEntry={!showPassword}
            />
            <TouchableOpacity
              style={styles.eyeIcon}
              onPress={() => setShowPassword(!showPassword)}
            >
              <Ionicons
                name={showPassword ? 'eye-off' : 'eye'}
                size={24}
                color="#666"
              />
            </TouchableOpacity>
          </View>

          <View style={styles.passwordContainer}>
            <TextInput
              style={styles.passwordInput}
              placeholder="Confirm Password"
              value={confirmPassword}
              onChangeText={setConfirmPassword}
              secureTextEntry={!showConfirmPassword}
            />
            <TouchableOpacity
              style={styles.eyeIcon}
              onPress={() => setShowConfirmPassword(!showConfirmPassword)}
            >
              <Ionicons
                name={showConfirmPassword ? 'eye-off' : 'eye'}
                size={24}
                color="#666"
              />
            </TouchableOpacity>
          </View>

          <TouchableOpacity 
            style={styles.button} 
            onPress={handleSignUp}
            disabled={loading}
          >
            {loading ? (
              <ActivityIndicator color="#fff" />
            ) : (
              <Text style={styles.buttonText}>Sign Up</Text>
            )}
          </TouchableOpacity>

          <TouchableOpacity onPress={() => navigation.navigate('SignIn')}>
            <Text style={styles.link}>Already have an account? Sign In</Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
  },
  scrollContent: {
    flexGrow: 1,
  },
  content: {
    flex: 1,
    justifyContent: 'center',
    padding: 20,
  },
  title: {
    fontSize: 32,
    fontWeight: 'bold',
    marginBottom: 8,
    textAlign: 'center',
  },
  subtitle: {
    fontSize: 16,
    color: '#666',
    marginBottom: 32,
    textAlign: 'center',
  },
  input: {
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 8,
    padding: 16,
    marginBottom: 16,
    fontSize: 16,
  },
  passwordContainer: {
    position: 'relative',
    marginBottom: 16,
  },
  passwordInput: {
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 8,
    padding: 16,
    paddingRight: 50,
    fontSize: 16,
  },
  eyeIcon: {
    position: 'absolute',
    right: 12,
    top: 12,
    padding: 4,
  },
  button: {
    backgroundColor: ZorliBrandKit.colors.vaultBlue,
    padding: 16,
    borderRadius: 8,
    alignItems: 'center',
    marginBottom: 16,
  },
  buttonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: '600',
  },
  link: {
    color: ZorliBrandKit.colors.vaultBlue,
    textAlign: 'center',
    fontSize: 14,
  },
  successIcon: {
    width: 96,
    height: 96,
    backgroundColor: '#E8F5E9',
    borderRadius: 48,
    alignItems: 'center',
    justifyContent: 'center',
    alignSelf: 'center',
    marginBottom: 24,
  },
  successTitle: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 16,
    textAlign: 'center',
  },
  successMessage: {
    fontSize: 16,
    color: '#666',
    marginBottom: 24,
    textAlign: 'center',
    lineHeight: 24,
  },
  infoBox: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#E3F2FD',
    padding: 12,
    borderRadius: 8,
    marginBottom: 24,
  },
